package com.aiuml.architect.diagram;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/diagrams") class DiagramController { private final DiagramService service; DiagramController(DiagramService s){service=s;} private UUID user(Authentication a){return UUID.fromString(a.getName());} @GetMapping List<DiagramService.DiagramSummary> list(@PathVariable UUID projectId,Authentication a){return service.list(projectId,user(a));} @PostMapping ResponseEntity<DiagramDocument> create(@PathVariable UUID projectId,Authentication a,@Valid @RequestBody DiagramDocument d){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(projectId,user(a),d));} @GetMapping("/{id}") DiagramDocument get(@PathVariable UUID projectId,@PathVariable UUID id,Authentication a){return service.get(projectId,id,user(a));} @PutMapping("/{id}") DiagramDocument update(@PathVariable UUID projectId,@PathVariable UUID id,Authentication a,@Valid @RequestBody DiagramDocument d){return service.update(projectId,id,user(a),d);} @GetMapping("/{id}/versions") List<DiagramService.DiagramVersionResponse> versions(@PathVariable UUID projectId,@PathVariable UUID id,Authentication a){return service.versions(projectId,id,user(a));} @PostMapping("/{id}/versions/{version}/restore") DiagramDocument restore(@PathVariable UUID projectId,@PathVariable UUID id,@PathVariable int version,Authentication a){return service.restore(projectId,id,user(a),version);} }
